<script>document.getElementById('book-format')?.addEventListener('change', function(){document.getElementById('pdf-field').style.opacity = this.value === 'ebook' ? '1' : '.55';});(()=>{const initial=new URLSearchParams(location.search).get('tab')||'add';const show=tab=>{document.querySelectorAll('.book-tab').forEach(button=>button.classList.toggle('active',button.dataset.tab===tab));document.querySelectorAll('.book-tab-panel').forEach(panel=>panel.hidden=panel.dataset.panel!==tab);history.replaceState(null,'',location.pathname+(tab==='add'?'':'?tab='+tab));};document.querySelectorAll('.book-tab').forEach(button=>button.addEventListener('click',()=>show(button.dataset.tab)));show(['add','listing','gallery'].includes(initial)?initial:'add');})();</script>
